import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"越调·小桃红淮安道中","description":"","frontmatter":{"title":"越调·小桃红淮安道中","date":"2026-11-11T00:00:00.000Z","seq":34,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/越调·小桃红淮安道中.md","filePath":"blogs/元曲·张可久/越调·小桃红淮安道中.md"}'),o={name:"blogs/元曲·张可久/越调·小桃红淮安道中.md"};function c(l,a,n,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="越调·小桃红淮安道中" tabindex="-1">越调·小桃红淮安道中 <a class="header-anchor" href="#越调·小桃红淮安道中" aria-label="Permalink to &quot;越调·小桃红淮安道中&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">一篙新水绿于蓝，柳岸渔灯暗。</p><p class="poem-stanza">桥畔寻诗驻时暂，散晴岚，依微半幅云烟淡。</p><p class="poem-stanza">杨花乱糁，扁舟初缆，风景似江南。</p><p class="poem-stanza">秋宵有怀满庭落叶响哀蝉，秋入生绡扇。</p><p class="poem-stanza">池上芙蓉锦成片，雨余天，倚阑中欠如花面。</p><p class="poem-stanza">诗题翠笺，香销金串，罗帐又孤眠。</p><p class="poem-stanza">游仙梦白云堆里听松风，一枕游仙梦。</p><p class="poem-stanza">相伴琼姬玉华洞，锦重重，觉来香露冷衣重。</p><p class="poem-stanza">长桥彩虹，空台丹凤，花影月明中。</p><p class="poem-stanza">春思燕南雁北几相思，无限相思事。</p><p class="poem-stanza">两袖啼痕粉香渍，牡丹时，日长不见音书至。</p><p class="poem-stanza">东墙柳丝，知人独自，憔悴舞腰枝。</p><p class="poem-stanza">秋感锦书红泪两三行，血点花梢上。</p><p class="poem-stanza">小字平安寄无恙，雁成双，玉奴更上西楼望。</p><p class="poem-stanza">月明绣窗，灯昏罗帐，今夜梦才郎。</p><p class="poem-stanza">寄春谷王千户紫箫声冷彩云空，十载扬州梦。</p><p class="poem-stanza">一点红香锦胡同，倚东风，娇花宠柳春权重。</p><p class="poem-stanza">鞭催玉骢，酒携金凤，半醉月明中。</p><p class="poem-stanza">春深一汀烟柳索春饶，添得杨花闹。</p><p class="poem-stanza">盼煞归舟木兰棹，水迢迢，画楼明月空相照。</p><p class="poem-stanza">今番瘦了，多情知道，宽尽翠裙腰。</p><p class="poem-stanza">秋江晚兴锦鸳凉羽翠莲香，船舣秋江上。</p><p class="poem-stanza">别后佳人想无恙，暮云长，雁归曾倚西楼望。</p><p class="poem-stanza">红衫旧腔，花钿新样，封寄柳枝娘。</p></div>',3)])])}const d=s(o,[["render",c]]);export{i as __pageData,d as default};
